def shell(title,description,body,base='./',active='',path='',lang='en',homepage=False):
 support_assets='<link rel="stylesheet" href="support.css?v=mobile-ux-v1"><script src="support.js?v=20261108" defer></script>' if path=='support/' else ''
 structured={'@context':'https://schema.org','@type':'SoftwareApplication'if homepage else'WebPage','name':'GØ-404'if homepage else title,'description':description,'inLanguage':lang}
 if homepage:structured.update(applicationCategory='MusicApplication',operatingSystem='iOS')
 url=origin.rstrip('/')+'/'+path
 structured['url']=url
 data=json.dumps(structured,ensure_ascii=False,separators=(',',':'));hashes.append(base64.b64encode(hashlib.sha256(data.encode()).digest()).decode())
 alternates=(''.join(f'<link rel="alternate" hreflang="{code}" href="{origin}/{route}">'for code,route in [('en',''),('pl','pl/'),('x-default','')]))if homepage else''
 homepage_css='<link rel="stylesheet" href="/assets/home.css?v=news-link-20261114">'if homepage else''
 newsletter_assets='<script src="/assets/newsletter-frame.js?v=20261112" defer></script>' if homepage and C.get('newsletter_form_url') else ''
 preload='<link rel="preload" href="/assets/machine-phone-mobile.svg?v=ux-v1" as="image">'if homepage else''
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#080808"><meta name="description" content="{esc(description)}"><meta name="robots" content="{'noindex, nofollow'if C['preview']else'index, follow'}"><title>{esc(title)}</title><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:site_name" content="GØ-404"><meta property="og:locale" content="{'pl_PL'if lang=='pl'else'en_US'}"><link rel="canonical" href="{url}"><meta property="og:url" content="{url}"><meta property="og:image" content="{origin}/assets/machine-empty.png?v=empty-grid-20261108">{alternates}<link rel="icon" href="/assets/favicon.png" type="image/png"><link rel="preload" href="/assets/fonts/Manrope.ttf" as="font" type="font/ttf" crossorigin><link rel="preload" href="/assets/fonts/BarlowCondensed-Bold.ttf" as="font" type="font/ttf" crossorigin>{preload}<link rel="stylesheet" href="/assets/site.css?v=mobile-ux-v1">{homepage_css}{newsletter_assets}<script src="/assets/site.js?v=mobile-ux-v4" defer></script>{support_assets}<script type="application/ld+json">{data}</script></head><body class="{'landing-page'if homepage else'document-page'}">{header(base,active,lang)}{body}{footer(base,lang)}<dialog class="image-dialog" aria-label="{'Szczegóły interfejsu GØ-404'if lang=='pl'else'GØ-404 interface detail'}"><button class="dialog-close" aria-label="{'Zamknij zdjęcie'if lang=='pl'else'Close image'}">{'ZAMKNIJ'if lang=='pl'else'CLOSE'} ×</button><img alt=""></dialog></body></html>'''
hashes=[]
