faq=support_content['topics']
faq_html=''.join('<details id="'+esc(topic['id'])+'"><summary><span><small>'+esc(topic['category'])+'</small>'+esc(topic['title'])+'</span><span class="faq-plus" aria-hidden="true">+</span></summary><div class="faq-answer">'+''.join('<p>'+esc(paragraph)+'</p>' for paragraph in topic['paragraphs'])+'</div></details>' for topic in faq)
