csp="default-src 'self'; script-src 'self' "+' '.join("'sha256-"+h+"'"for h in hashes)+"; style-src 'self'; font-src 'self'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-src 'self' https://ab7bda5a.sibforms.com; frame-ancestors 'none'; form-action 'none'"
common_headers='/*\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Content-Type-Options: nosniff\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n'+('  X-Robots-Tag: noindex, nofollow\n'if C['preview']else'')
# The official form has its own narrowly scoped meta-CSP, allowing only Brevo resources.
page_headers=''.join('\n'+route+'\n  Content-Security-Policy: '+csp+'\n' for route in ['/', '/index.html', '/pl/', '/pl/index.html', '/support/*', '/privacy/*', '/pl/privacy/*', '/404.html'])
(D/'_headers').write_text(common_headers+page_headers+'\n/assets/*\n  Cache-Control: public, max-age=3600\n')
(D/'robots.txt').write_text('User-agent: *\n'+('Disallow: /\n'if C['preview']else'Allow: /\nSitemap: '+origin.rstrip('/')+'/sitemap.xml\n'))
if origin:(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+esc(origin.rstrip('/')+'/'+p)+'</loc></url>'for p in ['','pl/','support/','privacy/','pl/privacy/'])+'</urlset>')
(D/'.nojekyll').write_text('')
(S/'local-build-status.json').write_text(json.dumps({'pages':['/','/pl/','/support/','/privacy/','/pl/privacy/','/newsletter/'],'preview':C['preview'],'AppStoreURLConfigured':bool(store),'pricePublished':False,'hostingServiceCreated':False,'published':False,'dependenciesInstalled':False,'applicationFilesModified':False},indent=2));print('Built standalone static website, no publication.')
